//! 🧪️ Original donated SELECT controls distinguish missing selection, incomplete constructor and exact scalar.
use super::*;
use semio_framework_plugin::{AppRenderOperationContext,ChildContentView};
use semio_framework_ui_contract::{Component,OriginalBuiltTreeRetirement};
use semio_s_artifact_stdio_ifc_4_model::standards::v4::subsets::any::schema::snapshot::{IfcEntity,IfcComplexType};
fn select_source(law:&serde_json::Value,name:&str)->std::sync::Arc<IfcSnapshot>{let domain=law["domains"].as_array().unwrap().iter().find(|row|row["entity"]==name).unwrap();let lag=name=="IFCLAGTIME";let mut entities=vec![IfcEntity{id:1,name:name.into(),args:if lag{vec![IfcValue::Unset,IfcValue::Enum("WORKTIME".into())]}else{vec![IfcValue::Unset,IfcValue::Unset,IfcValue::Unset,IfcValue::Unset,IfcValue::Reference(7)]},complex:domain["ancestors"].as_array().unwrap().iter().map(|name|IfcComplexType{name:name.as_str().unwrap().into(),args:if name=="IFCSCHEDULINGTIME"{vec![IfcValue::String("original".into()),IfcValue::Enum("PREDICTED".into()),IfcValue::Unset]}else{Vec::new()}}).collect()}];if !lag{entities.extend([IfcEntity{id:7,name:"IFCPOLYLINE".into(),args:vec![IfcValue::Aggregate(vec![IfcValue::Reference(9),IfcValue::Reference(10)])],complex:Vec::new()},IfcEntity{id:9,name:"IFCCARTESIANPOINT".into(),args:vec![IfcValue::Aggregate(vec![IfcValue::Real(0.0),IfcValue::Real(0.0)])],complex:Vec::new()},IfcEntity{id:10,name:"IFCCARTESIANPOINT".into(),args:vec![IfcValue::Aggregate(vec![IfcValue::Real(1.0),IfcValue::Real(0.0)])],complex:Vec::new()}]);}std::sync::Arc::new(IfcSnapshot{entities,..Default::default()})}
#[test]
fn donated_select_controller_keeps_exact_members_and_scalar_inputs_editable_under_original_source(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../🔎️details/🧪️tests/type-select-input.json")).unwrap();for row in law["cases"].as_array().unwrap(){for mode in 0..3{let name=row["entity"].as_str().unwrap();let snapshot=select_source(&law,name);let history=semio_framework_plugin::HistoryView::empty();let view=staged_view();let operation=AppRenderOperationContext{app_instance_id:17,base_revision:semio_framework_job::RevisionId(0),generation:semio_framework_job::Generation(1),canonical_base_revision:[0;32],mounted_policy:semio_framework_plugin::app_testing::artifact_app_laws::fixture_mounted_policy()};let doc=semio_framework_async::poll::resolve_ready(ArtifactView::with_render_context(snapshot.as_ref(),&history,ChildContentView::EMPTY,operation,"actual-select-source",None));let mut caller=OriginalWorkFixture::new();let mut work=caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::begin_render_work(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,cx)).unwrap().unwrap();let scalar=if row["kind"]=="real"{serde_json::json!({"bits":row["raw"]})}else{row["raw"].clone()};let items=if mode==1{serde_json::json!([])}else{serde_json::json!([{"kind":row["kind"],"value":scalar}])};let rows=if mode==0{serde_json::json!([])}else{serde_json::json!([{"index":"0","value":{"kind":"typedValue","value":{"name":row["member"],"items":items}}}])};let args=serde_json::json!({"path":"/entities/0","value":{"$ifcType":name,"$ifcInputs":rows}});let parsed=semio_framework_pack_json::parse(&args.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let mut donor=Some(semio_framework_plugin::action_staging::StagedFormRequest{token:semio_framework_plugin::action_staging::StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:view.window_id.as_ref().unwrap().clone(),generation:"1".into(),revision:"0".repeat(64)},locale:view.locale,args:semio_framework_pack_json::to_dsl_value(&parsed),page:None});
  for _ in 0..16{if caller.work_turn(staged_grant(),1000,|cx|Ifc4x3AnyEditor::receive_render_work_request(&mut work,&mut donor,&view,cx)).unwrap().is_some(){break;}}assert!(donor.is_none());let mut output=None;for _ in 0..1000000{match caller.work_turn(staged_grant(),1000,|cx|Ok(work.render(semio_framework_plugin::action_staging::STAGED_FORM_BODY_KEY,&snapshot,&doc,&view,cx))).unwrap(){Ok(Some(tree))=>{output=Some(tree);break;},Ok(None)=>{},Err(_)=>panic!("SELECT draft stays editable: {} mode {}",row["id"],mode)}}let tree=output.unwrap();let Component::Extension(status)=&tree.root.children.get(0).unwrap().component else{panic!("original status")};assert_eq!(serde_json::to_value(&status.props).unwrap()["ready"],mode==2&&row["admitted"].as_bool().unwrap());let fields=tree.root.children.iter().skip(1).collect::<Vec<_>>();assert_eq!(fields.len(),if mode==0{1}else{2});let Component::Select(member)=&fields[0].children.get(0).unwrap().component else{panic!("declared member control")};assert_eq!(member.value.as_ref(),if mode==0{""}else{row["member"].as_str().unwrap()});assert_eq!(member.items.len(),2);assert!(!fields[0].children.get(0).unwrap().bindings.is_empty());if mode>0{let node=fields[1].children.get(0).unwrap();let Component::Input(props)=&node.component else{panic!("typed selected scalar")};assert_eq!(props.value.as_ref(),if mode==1{""}else{row["raw"].as_str().unwrap()});assert!(!node.bindings.is_empty());}
  let mut close=OriginalBuiltTreeRetirement::new(tree.root);for _ in 0..1000000{if close.terminal_is_empty(){break;}caller.turn(staged_grant(),|cx|cx.with_original_retirement(|cx|{let demand=close.next_demand(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|close.step(grant))?;Ok(())})).unwrap();}assert!(close.terminal_is_empty());caller.cancel().cancel_now();retire_staged(&mut caller,&mut Some(work));assert_eq!(std::sync::Arc::strong_count(&snapshot),1);caller.finish();}}
}
